if(!brokerContext&&!ownerContext&&visitRequested&&(decision.profile==='inquilino'||source.memory?.profile==='inquilino'||intent==='buscar_imovel')){
  const currentCode=current.match(/\bR-\d+\b/i)?.[0]||null;
  if(currentCode&&!merged.imovel_codigo) merged.imovel_codigo=currentCode.toUpperCase();
  decision.qualification_patch=merged;
  const identified=!!(merged.imovel_codigo||merged.anuncio_url||/\b(opcao|opção)\s*[1-3]\b|\b(primeir[oa]|segund[oa]|terceir[oa])\b|\b(esse|este|aquele)\s+(?:imovel|apartamento|galpao|casa)\b/.test(normalized));
  if(identified){
    decision.action='handoff';decision.handoff_required=true;
    decision.handoff_reason='Cliente quer agendar visita'+(merged.imovel_codigo?' ao imóvel '+merged.imovel_codigo:'');
    decision.reply='Perfeito. Vou encaminhar para nossa equipe combinar a visita com você.';
    decision.next_step='aguardar_agendamento_humano';
  }else{
    decision.action='ask';decision.handoff_required=false;
    decision.reply='Claro. Qual imóvel você quer visitar? Pode me mandar o código ou o link?';
    decision.next_step='identificar_imovel_visita';
  }
  decision.knowledge_gap=false;
}
// O modelo pode afirmar uma política inexistente mesmo instruído a não fazê-lo.
// Para perguntas operacionais factuais, ausência de fonte aprovada força humano.
const asksFactualQuestion=/[?]|\b(qual|quanto|como funciona|quando|me explica|pode (me )?(informar|dizer)|gostaria de saber)\b/.test(normalized);
const catalogQuestion=/\b(imovel|imoveis|apartamento|casa|galpao|sala|loja|kitnet|studio)\b/.test(normalized)&&/\b(tem|disponiv|opcoes|buscar|encontrar|mostra)\b/.test(normalized);
const operationalQuestion=(asksFactualQuestion&&!catalogQuestion)||/\b(taxa de administracao|qual o prazo|quanto custa|valor da taxa|valor da comissao)\b/.test(normalized);
const brokerPolicyQuestion=brokerContext&&/\b(comissao|indicacao|captacao|parceria|primeiro aluguel)\b/.test(normalized);
const knownIntakeQuestion=(ownerContext&&!ownerFactualQuestion)||visitRequested;
if(operationalQuestion&&!brokerPolicyQuestion&&!knownIntakeQuestion&&!(source.knowledge_entry_ids||[]).length){
  decision.knowledge_gap=true;
}
if((ownerFeeQuestion&&!feeApproved)||(ownerDeadlineQuestion&&!deadlineApproved)||(ownerGuaranteeQuestion&&!guaranteeApproved)||(ownerTermsQuestion&&!termsApproved)){
  decision.knowledge_gap=true;
}
if(decision.knowledge_gap===true){
  decision.action='handoff';
  decision.handoff_required=true;
  decision.handoff_reason=decision.handoff_reason||'Pergunta sem resposta confirmada na base de conhecimento';
  decision.reply='Quero te passar a informação certa. Vou encaminhar sua pergunta para nossa equipe conferir e continuar com você por aqui.';
  decision.next_step='aguardar_resposta_humana';
}
// Referências inequívocas a atendimento anterior sem histórico visível
// vão para a equipe. Nunca completar lacunas com suposições.
const previousMessages=Array.isArray(source.memory?.messages)?source.memory.messages:[];
const previousOutbounds=previousMessages.filter(m=>m.direction==='outbound');
const hasSubstantivePriorReply=Boolean(source.memory?.conversation_summary)||previousOutbounds.some(m=>{
  const text=norm(m.content);
  return text.length>90&&!/como posso te ajudar/.test(text);
});
const referencesUnseenHistory=/\b(conforme (?:combinamos|falamos|conversei)|como (?:combinamos|falamos)|ja (?:falei|conversei|enviei|tratei)|falei com (?:voces|alguem|um atendente)|(?:ontem|antes) (?:falei|conversei) com voces|(?:aquele|aquela|o mesmo|a mesma) (?:imovel|apartamento|casa|galpao|visita|proposta|contrato|atendimento)|(?:minha|meu) (?:visita|proposta|contrato|cadastro|atendimento) (?:anterior|que (?:agendei|enviei|fiz))|como (?:esta|ficou) (?:a|o) (?:minha visita|meu contrato|meu processo|minha proposta)|quero (?:retomar|continuar) (?:o |a )?(?:atendimento|conversa)|tem alguma (?:novidade|atualizacao)|alguma resposta sobre)\b/.test(normalized);
if(!hasSubstantivePriorReply&&referencesUnseenHistory){
  decision.action='handoff';
  decision.handoff_required=true;
  decision.handoff_reason='Cliente retoma atendimento anterior sem histórico disponível para a LIA';
  decision.reply='Entendi. Para continuar com o contexto certo, vou passar sua mensagem para nossa equipe. Alguém vai seguir com você por aqui em breve.';
  decision.next_step='aguardar_retomada_humana';
  decision.knowledge_gap=false;
}
return [{json:{session_id:source.session_id,contact_id:source.contact_id||null,phone:source.phone||source.memory?.phone||null,instance:source.instance||null,batch_id:source.batch_id,message_count:source.message_count||1,combined_content:source.combined_content,memory:source.memory,response_id:response.id||null,model:response.model||null,usage:response.usage||null,...decision}}];

const original = $('04 Interpretar decisao').first().json;
const current = $json || {};
return [{json: current.action === 'property_results' ? {...original, ...current} : original}];
